import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { describe, expect, it } from "vitest";
import { buildMcpInstructions } from "./mcpInstructions.js";
import { createMcpServer } from "./mcpServer.js";
const TEST_PLATFORM = {
    authPath: "test",
    loginHint: "/test:login",
    setupHint: "/test:setup",
    updateHint: "/test:update",
    repo: "Test/test-plugin",
    remotePackageJsonPath: "package.json",
    cliBinary: "test",
    displayName: "Test",
    supportsAutoUpdate: false,
    marketplaceName: "test",
    pluginName: "test",
    marketplacePreRegistered: false,
    pluginUpdateCommands: [],
};
const CLAUDE_CODE_INSTRUCTIONS_LIMIT = 4096;
const OLDER_CLAUDE_CODE_INSTRUCTIONS_LIMIT = 2048;
const LONGEST_HINTS_PLATFORM = {
    ...TEST_PLATFORM,
    setupHint: "/bitfab:setup",
    updateHint: "codex plugin marketplace upgrade bitfab",
};
async function connectClient() {
    const { server } = createMcpServer(TEST_PLATFORM, () => ({
        serviceUrl: "http://unused.test",
        apiKey: null,
        verbose: false,
        debug: false,
        sessionLogConsent: null,
    }), "0.0.0-test");
    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    const client = new Client({ name: "test-client", version: "0.0.0" });
    await Promise.all([
        server.connect(serverTransport),
        client.connect(clientTransport),
    ]);
    return client;
}
function toolNamesOutsideCode(text) {
    const prose = text.replace(/`[^`]*`/g, "");
    return [...new Set(prose.match(/\b[a-z]+(?:_[a-z]+)+\b/g) ?? [])];
}
describe("Bitfab MCP server instructions", () => {
    it("sends a usage guide to every connecting client", async () => {
        const client = await connectClient();
        const instructions = client.getInstructions() ?? "";
        expect(instructions).toContain("There is no special command for this work");
        expect(instructions).toContain("bitfab-replay --registry <registry-path>");
        expect(instructions).toContain("--dataset-id <dataset-id>");
        expect(instructions).toContain("--resume <experiment-id>");
        expect(instructions).toContain("--from-trace <trace-id>");
        expect(instructions).toContain("runs side effects for real");
        expect(instructions).toContain("--experiment-group-id");
        expect(instructions).toContain("`/test:setup`");
        expect(instructions).toContain("`/test:update`");
    });
    it("tells the agent every replay names one of the six code change types", async () => {
        const client = await connectClient();
        const instructions = client.getInstructions() ?? "";
        expect(instructions).toContain("Every replay needs `--code-change`");
        for (const type of [
            "working-tree",
            "last-branch",
            "default-branch",
            "ref",
            "skip",
            "manual",
        ]) {
            expect(instructions).toContain(`\`${type}\``);
        }
        expect(instructions).toContain("--code-change-file <path>");
        expect(instructions).toContain("--code-change-base <branch|sha>");
        expect(instructions).toContain("resume it with the same command plus `--resume <experiment-id>`");
    });
    it("names only tools the server registers", async () => {
        const client = await connectClient();
        const instructions = client.getInstructions() ?? "";
        const { tools } = await client.listTools();
        const registered = new Set(tools.map((tool) => tool.name));
        const named = toolNamesOutsideCode(instructions);
        expect(named.length).toBeGreaterThan(10);
        expect(named.filter((name) => !registered.has(name))).toEqual([]);
    });
    it("fits within Claude Code's instructions limit, with replay guidance inside the older limit", () => {
        const instructions = buildMcpInstructions(LONGEST_HINTS_PLATFORM);
        const olderLimitPart = instructions.slice(0, OLDER_CLAUDE_CODE_INSTRUCTIONS_LIMIT);
        expect(instructions.length).toBeLessThanOrEqual(CLAUDE_CODE_INSTRUCTIONS_LIMIT);
        expect(olderLimitPart).toContain("bitfab-replay --registry <registry-path>");
        expect(olderLimitPart).toContain("--resume <experiment-id>");
        expect(olderLimitPart).toContain("--from-trace <trace-id>");
    });
    it("never points at the retired assistant", async () => {
        const client = await connectClient();
        expect(client.getInstructions()).not.toMatch(/assistant/i);
    });
});
